1	export function getErrorMessage(error: unknown, fallback = "Unknown error"): string {
2	  if (error instanceof Error) {
3	    return error.message;
4	  }
5	
6	  if (typeof error === "string") {
7	    return error;
8	  }
9	
10	  if (error && typeof error === "object" && "message" in error) {
11	    return String(error.message);
12	  }
13	
14	  return fallback;
15	}
16	
17	export function handleError(
18	  error: unknown,
19	  toast: (message: string) => void,
20	  options?: {
21	    context?: string;
22	    fallbackMessage?: string;
23	    onError?: (error: unknown) => void;
24	  },
25	): void {
26	  const contextPrefix = options?.context ? `${options.context}: ` : "";
27	  const fallback = options?.fallbackMessage;
28	
29	  const errorMessage = options?.context ? `${contextPrefix}${getErrorMessage(error, fallback)}` : getErrorMessage(error, fallback);
30	
31	  console.error(error);
32	  toast(errorMessage);
33	  options?.onError?.(error);
34	}
35	
36	export function isError(value: unknown): value is Error {
37	  return value instanceof Error;
38	}
